import React from "react";
import { Link } from "react-router-dom";
import { FaSearch, FaBars, FaThLarge, FaSlidersH } from "react-icons/fa";
import { apiGet } from "../common/api";
import GenericTable from "../components/GenericTable";
import Loader from "../common/Loader";
import TechnicianNavbar from "../components/TechnicianNavbar";

// رنگ وضعیت بر اساس فیلدهای درخواست
function statusColor(request) {
  if (request.status === -1) return "#e05a5a"; // لغو شده
  if (request.end === 1) return "#34c759"; // تسویه شده
  return "#5b9bf0"; // در حال انجام
}

// کارت یک سابقه، برای حالت گرید
function HistoryCard({ request }) {
  return (
    <div className="border rounded-4 p-3 bg-white h-100 d-flex flex-column">
      <div className="d-flex align-items-center justify-content-between mb-2">
        <span className="text-dark">{request.name}</span>
        <span className="text-muted small">مشتری</span>
      </div>
      <div className="d-flex align-items-center justify-content-between mb-2">
        <span className="text-dark">{request.device_type}</span>
        <span className="text-muted small">نوع دستگاه</span>
      </div>
      <div className="d-flex align-items-center justify-content-between mb-3">
        <span className="text-dark">{request.problem}</span>
        <span className="text-muted small">ایراد دستگاه</span>
      </div>
      <Link to={`/requests/history/${request.id}`} className="btn btn-outline-primary rounded-3 mt-auto">
        دیدن جزئیات
      </Link>
    </div>
  );
}

// صفحه‌ی «سوابق» — تاریخچه‌ی درخواست‌هایی که تعمیرکار قبول کرده، از GET /my-list می‌آد
class MyRequestsHistoryPage extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      requests: [],
      loading: true,
      searchTerm: "",
      viewMode: "list",
    };
    this.handleSearchChange = this.handleSearchChange.bind(this);
  }

  componentDidMount() {
    apiGet("/my-list")
      .then((json) => {
        this.setState({ requests: json.requests || [], loading: false });
      })
      .catch(() => {
        this.setState({ loading: false });
      });
  }

  handleSearchChange(e) {
    this.setState({ searchTerm: e.target.value });
  }

  render() {
    const { requests, loading, searchTerm, viewMode } = this.state;

    const filtered = requests.filter((r) => {
      const term = searchTerm.trim();
      if (!term) return true;
      return (r.name || "").includes(term) || (r.device_type || "").includes(term);
    });

    const columns = [
      { key: "name", label: "نام مشتری", headerClassName: "text-primary" },
      { key: "device_type", label: "نوع دستگاه", headerClassName: "text-primary" },
      { key: "problem", label: "ایراد دستگاه", headerClassName: "text-primary" },
      {
        key: "details",
        label: "جزئیات",
        width: "0.6fr",
        headerClassName: "text-primary",
        render: (row) => (
          <div className="d-flex align-items-center justify-content-center gap-2">
            <span
              className="rounded-circle"
              style={{ width: 14, height: 14, backgroundColor: statusColor(row) }}
            />
            <FaSlidersH className="text-secondary" size={13} style={{ transform: "rotate(90deg)" }} />
          </div>
        ),
      },
    ];

    return (
      <div dir="rtl" lang="fa" className="bg-white min-vh-100">
        {loading && <Loader />}

        <div className="container-fluid px-3 pt-4" style={{ maxWidth: 480, margin: "0 auto", paddingBottom: 100 }}>
          <div className="d-flex align-items-center gap-2 border rounded-pill px-3 py-2 mb-3 bg-white">
            <input
              type="text"
              placeholder="جستجو..."
              value={searchTerm}
              onChange={this.handleSearchChange}
              className="form-control border-0 shadow-none text-end p-0"
            />
            <FaSearch className="text-secondary" size={16} />
          </div>

          <div className="d-flex align-items-center gap-2 mb-3">
            <button
              type="button"
              onClick={() => this.setState({ viewMode: "list" })}
              className={`btn ${viewMode === "list" ? "btn-light border-primary text-primary" : "btn-light border"} rounded-3 p-2`}
            >
              <FaBars size={16} />
            </button>
            <button
              type="button"
              onClick={() => this.setState({ viewMode: "grid" })}
              className={`btn ${viewMode === "grid" ? "btn-light border-primary text-primary" : "btn-light border"} rounded-3 p-2`}
            >
              <FaThLarge size={16} />
            </button>
          </div>

          {filtered.length === 0 && !loading && (
            <div className="text-center text-muted py-5">موردی برای نمایش وجود ندارد.</div>
          )}

          {viewMode === "grid" ? (
            <div className="row g-3">
              {filtered.map((r) => (
                <div key={r.id} className="col-6">
                  <HistoryCard request={r} />
                </div>
              ))}
            </div>
          ) : (
            <GenericTable
              columns={columns}
              rows={filtered}
              getRowLink={(row) => `/requests/history/${row.id}`}
            />
          )}
        </div>

        <TechnicianNavbar />
      </div>
    );
  }
}

export default MyRequestsHistoryPage;
